  1	import { existsSync, readdirSync, readFileSync } from "node:fs";
  2	import { join } from "node:path";
  3	import { describe, expect, it } from "vitest";
  4	import vocabularyData from "../../vocabulary/data/vocabulary.json";
  5	import type { VocabEntry } from "../../vocabulary/types";
  6	import {
  7		DECK_LESSON_IDS,
  8		deckPathForLesson,
  9		resolveLessonContent,
 10		validateDeck,
 11	} from "./lessonContent";
 12	import { checkOriginality } from "./originality";
 13	import { classifyConsonant } from "./soundType";
 14	import {
 15		consonants,
 16		lessons,
 17		type ThaiConsonant,
 18		ThaiSymbolClass,
 19	} from "./symbols";
 20	
 21	/**
 22	 * Task 2.5's proof: the opening band's five in-house decks, and the lesson
 23	 * that turns consonant class from 44 memorised facts into two audible buckets
 24	 * plus a small residue.
 25	 *
 26	 * Everything here reads the *committed* decks under `public/lessons/`, not a
 27	 * fixture — the artefacts the app serves are the artefacts under test. The
 28	 * lesson's rule is likewise read off the deck rather than restated here: the
 29	 * third bucket's members come out of the slide that names them, so a lesson
 30	 * that stopped naming one would stop being able to place it.
 31	 */
 32	
 33	const REPO_ROOT = join(import.meta.dirname, "..", "..", "..", "..");
 34	const PUBLIC_LESSONS = join(REPO_ROOT, "public", "lessons");
 35	const SCRIPTS = join(REPO_ROOT, "content", "lessons");
 36	
 37	/** The slide whose body states which third-bucket letters are known so far. */
 38	const THIRD_BUCKET_SLIDE = "bucket-three";
 39	const BUCKETS_LESSON_ID = "lesson-sound-buckets";
 40	/** The first lesson after the band — still on the licensed video arm. */
 41	const FIRST_LESSON_AFTER_BAND = "lesson-06";
 42	
 43	interface BandLesson {
 44		readonly id: string;
 45		/**
 46		 * The `lessons`-table row this deck teaches, where there is one.
 47		 * `lesson-sound-buckets` has none: it introduces no symbol, so it declares
 48		 * no row, and the sequence entry that would give it one is owned by
 49		 * `lessonSequence.ts` (see the note on `describe("the content seam")`).
 50		 */
 51		readonly legacyNumber?: number;
 52	}
 53	
 54	/** Declaration order is the order the learner meets them. */
 55	const BAND: readonly BandLesson[] = [
 56		{ id: "lesson-01", legacyNumber: 1 },
 57		{ id: "lesson-02", legacyNumber: 2 },
 58		{ id: "lesson-03", legacyNumber: 3 },
 59		{ id: "lesson-04", legacyNumber: 4 },
 60		{ id: "lesson-05", legacyNumber: 5 },
 61		{ id: BUCKETS_LESSON_ID },
 62	];
 63	
 64	type RawSlide = {
 65		kind: string;
 66		id: string;
 67		heading?: string;
 68		body?: string[];
 69		prompt?: string;
 70		answers?: string[];
 71		revealSlideId?: string;
 72		retrievalSlideId?: string;
 73		audio?: string[];
 74		image?: string;
 75	};
 76	type RawDeck = {
 77		lessonId: string;
 78		title: string;
 79		slides: RawSlide[];
 80		teachingWords?: { thai: string; reason: string }[];
 81	};
 82	type Manifest = { lessonId: string; assets: { path: string | null }[] };
 83	
 84	const THAI = /[฀-๿]/g;
 85	const THAI_RUN = /[฀-๿]+/g;
 86	
 87	function lessonDir(id: string): string {
 88		return join(PUBLIC_LESSONS, id);
 89	}
 90	
 91	function readDeck(id: string): RawDeck {
 92		return JSON.parse(
 93			readFileSync(join(lessonDir(id), "deck.json"), "utf-8"),
 94		) as RawDeck;
 95	}
 96	
 97	function readManifest(id: string): Manifest {
 98		return JSON.parse(
 99			readFileSync(join(lessonDir(id), "manifest.json"), "utf-8"),
100		) as Manifest;
101	}
102	
103	/** Every piece of learner-facing prose on a deck, in slide order. */
104	function textsOf(deck: RawDeck): string[] {
105		const texts: string[] = [deck.title];
106		for (const slide of deck.slides) {
107			if (slide.heading) texts.push(slide.heading);
108			if (slide.prompt) texts.push(slide.prompt);
109			texts.push(...(slide.body ?? []));
110			texts.push(...(slide.answers ?? []));
111		}
112		return texts;
113	}
114	
115	function thaiCharsIn(texts: readonly string[]): Set<string> {
116		const chars = new Set<string>();
117		for (const text of texts)
118			for (const ch of text.match(THAI) ?? []) chars.add(ch);
119		return chars;
120	}
121	
122	/** Runs of two or more Thai characters — words, as opposed to bare letters. */
123	function thaiWordsIn(texts: readonly string[]): Set<string> {
124		const words = new Set<string>();
125		for (const text of texts) {
126			for (const run of text.match(THAI_RUN) ?? []) {
127				if (run.length >= 2) words.add(run);
128			}
129		}
130		return words;
131	}
132	
133	/**
134	 * Symbols a `lessons` row declares. The table stores combining vowels with a
135	 * dotted-circle-free leading space (`" ี"`), so the Thai characters are pulled
136	 * out rather than the strings compared.
137	 */
138	function declaredSymbols(legacyNumber: number | undefined): Set<string> {
139		if (legacyNumber === undefined) return new Set();
140		const row = lessons.find((lesson) => lesson.number === legacyNumber);
141		if (!row) return new Set();
142		return thaiCharsIn([...row.consonants, ...row.vowels]);
143	}
144	
145	/**
146	 * Symbols a lesson shows without teaching, declared in its script's own
147	 * comment block as `previews: <glyph> — <why>`. A deck may only reach outside
148	 * the taught set through one of these, and a declaration with no reason does
149	 * not count — which is what stops "previews:" becoming a blanket exemption.
150	 */
151	function declaredPreviews(id: string): Set<string> {
152		const source = readFileSync(join(SCRIPTS, `${id}.md`), "utf-8");
153		const previews = new Set<string>();
154		for (const line of source.matchAll(/^previews:\s*(.+)$/gm)) {
155			const body = line[1];
156			if (body.trim() === "none") continue;
157			const [glyphs, ...rest] = body.split("—");
158			if (rest.join("—").trim().length === 0) continue;
159			for (const ch of glyphs.match(THAI) ?? []) previews.add(ch);
160		}
161		return previews;
162	}
163	
164	/** Sentences, split only on terminal punctuation so a clause keeps its glyphs. */
165	function sentencesOf(text: string): string[] {
166		return text
167			.split(/(?<=[.?!])\s+/)
168			.map((s) => s.trim())
169			.filter((s) => s.length > 0);
170	}
171	
172	/**
173	 * Does this sentence assign a consonant class? Both channels count: the words
174	 * "low/mid/high class", and the three district names, because a district *is*
175	 * the class said without the word (sceneGrammar.ts).
176	 */
177	const CLASS_CLAIM =
178		/\b(?:low|mid|high)[\s-]?class\b|\b(?:temple|market|harbor)\b/i;
179	
180	const vocabulary = vocabularyData as unknown as VocabEntry[];
181	const vocabularyByThai = new Set(vocabulary.map((entry) => entry.thai));
182	
183	const decks = new Map(BAND.map((lesson) => [lesson.id, readDeck(lesson.id)]));
184	
185	/** Consonants the band has taught by the end of each of its lessons. */
186	const taughtAfter = new Map<string, Set<string>>();
187	{
188		const running = new Set<string>();
189		for (const lesson of BAND) {
190			for (const ch of declaredSymbols(lesson.legacyNumber)) running.add(ch);
191			taughtAfter.set(lesson.id, new Set(running));
192		}
193	}
194	
195	const consonantsTaughtInBand = [...(taughtAfter.get(BUCKETS_LESSON_ID) ?? [])]
196		.map((ch) => consonants.find((c) => c.character === ch))
197		.filter((c): c is ThaiConsonant => c !== undefined);
198	
199	// ============================================================================
200	// The rule, as the lesson states it

