200	// The rule, as the lesson states it
201	// ============================================================================
202	
203	type StatedRuleOutcome =
204		| { placed: true; consonantClass: ThaiSymbolClass; bucket: string }
205		| { placed: false; reason: string };
206	
207	/**
208	 * Apply the derivable-buckets rule exactly as `lesson-sound-buckets` states
209	 * it. Buckets one and two come from the sound alone — `classifyConsonant`'s
210	 * own derivation, which reads `initialSound` and `isAspirated` and no table.
211	 * The third bucket is deliberately *not* derived: the lesson defers the split
212	 * and names the letters it has already taught, so this consults that list and
213	 * nothing else. A letter the lesson never names comes back unplaced.
214	 */
215	function classFromStatedRule(
216		symbol: ThaiConsonant,
217		namedLowInThirdBucket: ReadonlySet<string>,
218	): StatedRuleOutcome {
219		const sound = classifyConsonant({
220			character: symbol.character,
221			initialSound: symbol.initialSound,
222			isAspirated: symbol.isAspirated,
223		});
224		if (sound.state !== "classified") {
225			return { placed: false, reason: sound.reason };
226		}
227		if (sound.soundType === "sonorant") {
228			return {
229				placed: true,
230				consonantClass: ThaiSymbolClass.Low,
231				bucket: "one — it can be hummed",
232			};
233		}
234		if (sound.soundType === "unaspirated-obstruent") {
235			return {
236				placed: true,
237				consonantClass: ThaiSymbolClass.Mid,
238				bucket: "two — it stops and releases no breath",
239			};
240		}
241		if (namedLowInThirdBucket.has(symbol.character)) {
242			return {
243				placed: true,
244				consonantClass: ThaiSymbolClass.Low,
245				bucket: "three — the lesson names it among the ones met so far",
246			};
247		}
248		return {
249			placed: false,
250			reason: `bucket three, and the lesson presents nothing that places ${symbol.character}`,
251		};
252	}
253	
254	/** The third-bucket letters the buckets lesson itself claims are low class. */
255	function namedLowInThirdBucket(): Set<string> {
256		const deck = decks.get(BUCKETS_LESSON_ID);
257		const slide = deck?.slides.find((s) => s.id === THIRD_BUCKET_SLIDE);
258		const named = new Set<string>();
259		for (const text of slide?.body ?? []) {
260			for (const sentence of sentencesOf(text)) {
261				if (!/low[\s-]?class/i.test(sentence)) continue;
262				for (const ch of sentence.match(THAI) ?? []) named.add(ch);
263			}
264		}
265		return named;
266	}
267	
268	// ============================================================================
269	
270	/**
271	 * The seam, as far as this task can reach it.
272	 *
273	 * AC1 wants every band lesson resolving to the deck arm, and that is two
274	 * lines this task's `covers` does not include: `DECK_LESSON_IDS` in
275	 * `lessonContent.ts`, and a `lesson-sound-buckets` entry in
276	 * `lessonSequence.ts`. Until both land, lessons 02-05 still resolve to their
277	 * videos and `lesson-sound-buckets` is undeclared, so the deck-arm half of
278	 * AC1 is asserted nowhere and is deliberately not faked here.
279	 *
280	 * What is asserted is everything the decks themselves can carry: each one is
281	 * committed and schema-valid at exactly the path the deck arm would serve it
282	 * from, the first lesson past the band is still on the video arm, and nothing
283	 * is registered on the deck arm without a deck behind it — the invariant that
284	 * stays true, and worth keeping, once the wiring does land.
285	 */
286	describe("the content seam", () => {
287		it("has a committed, schema-valid deck at the exact path the deck arm serves, for every band lesson", () => {
288			for (const { id } of BAND) {
289				const path = deckPathForLesson(id);
290				expect(path).toEqual({
